const player = runtimeScene.getObjects('Player')[0];
if (!player) return;
const behavior = player.getBehavior('PlatformerObject');
let vars = player.getVariables();

if (behavior.isOnFloor()) {
    vars.get('CurrentJumps').setNumber(0);
}
if (runtimeScene.getGame().getInputManager().isKeyPressed(32)) {
    let currentJumps = vars.get('CurrentJumps').getAsNumber();
    if (behavior.isOnFloor()) {
        behavior.simulateJumpKey();
        vars.get('CurrentJumps').setNumber(1);
    } else if (currentJumps < 2) {
        behavior.simulateJumpKey();
        vars.get('CurrentJumps').setNumber(currentJumps + 1);
    }
}
if (!behavior.isOnFloor() && behavior.isCollidingWithWall()) {
    if (behavior.getCurrentSpeedY() > 100) behavior.setSpeedY(100);
}
